-- One-time anonymous chat allowance. Identity is an HMAC generated by the
-- server from the installation ID and trusted edge client IP; raw identifiers
-- are never stored. The atomic upsert prevents concurrent requests from
-- exceeding the five-credit lifetime allowance.
create table if not exists public.slickly_anonymous_chat_allowances (
  identity_hash text primary key
    check (identity_hash ~ '^[0-9a-f]{64}$'),
  credits_used integer not null default 0
    check (credits_used >= 0 and credits_used <= 5),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.slickly_anonymous_chat_allowances enable row level security;
revoke all on table public.slickly_anonymous_chat_allowances from public, anon, authenticated;
grant all on table public.slickly_anonymous_chat_allowances to service_role;

create or replace function public.consume_slickly_anonymous_chat_credit(
  p_identity_hash text,
  p_credit_limit integer default 5
)
returns table(allowed boolean, used integer, remaining integer)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_used integer;
begin
  if p_identity_hash is null or p_identity_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid anonymous identity';
  end if;
  -- The public allowance is intentionally fixed at five; callers cannot
  -- increase it by changing the RPC argument.
  if p_credit_limit is distinct from 5 then
    raise exception 'Invalid anonymous credit limit';
  end if;

  insert into public.slickly_anonymous_chat_allowances as allowance
    (identity_hash, credits_used)
  values (p_identity_hash, 1)
  on conflict (identity_hash) do update
    set credits_used = allowance.credits_used + 1,
        updated_at = now()
    where allowance.credits_used < 5
  returning credits_used into v_used;

  if not found then
    select allowance.credits_used
      into v_used
      from public.slickly_anonymous_chat_allowances as allowance
      where allowance.identity_hash = p_identity_hash;
    return query select false, coalesce(v_used, 5), 0;
    return;
  end if;

  return query select true, v_used, greatest(0, 5 - v_used);
end;
$$;

revoke all on function public.consume_slickly_anonymous_chat_credit(text, integer) from public, anon, authenticated;
grant execute on function public.consume_slickly_anonymous_chat_credit(text, integer) to service_role;
